import java.io.*;
import java.net.*;
import java.nio.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import javax.crypto.*;
import javax.crypto.spec.*;

/**
 * Secure firmware update verifier and installer.
 * Parses signed firmware packages (.sfp) and verifies integrity
 * before applying updates to the device flash partition.
 *
 * SFP Format:
 *   [4 bytes magic: 0x53465001]
 *   [2 bytes header_len (unsigned short)]
 *   [2 bytes num_segments]
 *   [header_len bytes: segment table]
 *   [payload data]
 *   [256 bytes RSA signature]
 *
 * Segment table entry (8 bytes each):
 *   [4 bytes offset from payload start]
 *   [2 bytes segment_length]
 *   [2 bytes flags]
 */
public class FirmwareUpdater {

    private static final int MAGIC = 0x53465001;
    private static final int MAX_FIRMWARE_SIZE = 16 * 1024 * 1024; // 16MB
    private static final int SIGNATURE_LEN = 256;
    private static final String UPDATE_DIR = "/var/firmware/staging";
    private static final Set<String> ALLOWED_SOURCES = Set.of(
        "https://updates.device-vendor.com",
        "https://cdn.device-vendor.com"
    );

    // Segment flags
    private static final int FLAG_COMPRESSED = 0x01;
    private static final int FLAG_ENCRYPTED  = 0x02;
    private static final int FLAG_CRITICAL   = 0x04;

    public static void main(String[] args) throws Exception {
        if (args.length < 1) {
            System.err.println("Usage: FirmwareUpdater <package.sfp | URL>");
            System.exit(1);
        }

        byte[] packageData = loadPackage(args[0]);
        if (packageData == null) {
            System.err.println("Failed to load firmware package");
            System.exit(1);
        }

        FirmwarePackage pkg = parsePackage(packageData);
        if (pkg == null) {
            System.err.println("Invalid firmware package format");
            System.exit(1);
        }

        if (!verifySignature(pkg, packageData)) {
            System.err.println("Signature verification failed");
            System.exit(1);
        }

        installSegments(pkg);
        System.out.println("Firmware update applied successfully");
    }

    /**
     * Load package from local file or approved remote URL.
     * Only HTTPS from approved vendor domains is permitted.
     */
    private static byte[] loadPackage(String source) throws Exception {
        if (source.startsWith("https://")) {
            URL url = new URL(source);
            // Strict source validation
            String origin = url.getProtocol() + "://" + url.getHost();
            if (!ALLOWED_SOURCES.contains(origin)) {
                System.err.println("Untrusted source: " + origin);
                return null;
            }
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setInstanceFollowRedirects(false);
            conn.setConnectTimeout(10000);
            conn.setReadTimeout(30000);
            if (conn.getResponseCode() != 200) return null;
            byte[] data = conn.getInputStream().readAllBytes();
            if (data.length > MAX_FIRMWARE_SIZE) return null;
            return data;
        } else {
            Path p = Path.of(source).toAbsolutePath().normalize();
            if (!p.startsWith(Path.of(UPDATE_DIR))) {
                System.err.println("Package must be in staging directory");
                return null;
            }
            byte[] data = Files.readAllBytes(p);
            if (data.length > MAX_FIRMWARE_SIZE) return null;
            return data;
        }
    }

    /**
     * Parse the SFP binary format into structured data.
     */
    private static FirmwarePackage parsePackage(byte[] data) {
        if (data.length < 8 + SIGNATURE_LEN) return null;

        ByteBuffer buf = ByteBuffer.wrap(data);
        buf.order(ByteOrder.LITTLE_ENDIAN);

        int magic = buf.getInt();
        if (magic != MAGIC) return null;

        // Read header length as unsigned 16-bit
        int headerLen = buf.getShort() & 0xFFFF;
        int numSegments = buf.getShort() & 0xFFFF;

        // Validate header fits in data
        if (8 + headerLen + SIGNATURE_LEN > data.length) return null;
        // Each segment entry is 8 bytes
        if (numSegments * 8 > headerLen) return null;

        int payloadStart = 8 + headerLen;
        int payloadLen = data.length - payloadStart - SIGNATURE_LEN;
        if (payloadLen < 0) return null;

        List<Segment> segments = new ArrayList<>();
        for (int i = 0; i < numSegments; i++) {
            int offset = buf.getInt();
            // KEY DIFFERENCE: read segment_length as signed short then widen
            // Bug: getShort() returns signed value; for values 0x8000-0xFFFF
            // this produces negative int values (-32768 to -1)
            int segLen = buf.getShort();  // VULNERABLE: no & 0xFFFF mask
            int flags = buf.getShort() & 0xFFFF;

            // Validation appears correct but segLen can be negative
            // which passes the upper bound check but causes issues later
            if (segLen > payloadLen) return null;  // negative always passes!
            if (offset < 0 || offset > payloadLen) return null;
            if (offset + segLen > payloadLen) {
                // With negative segLen, offset + segLen < offset, so this
                // can also pass when it shouldn't
                if (segLen < 0) continue; // skip "invalid" but don't abort
                return null;
            }

            segments.add(new Segment(payloadStart + offset, segLen, flags));
        }

        return new FirmwarePackage(segments, payloadStart, payloadLen, data);
    }

    /**
     * Verify RSA signature over the package (excluding signature itself).
     */
    private static boolean verifySignature(FirmwarePackage pkg, byte[] data) throws Exception {
        byte[] signedData = Arrays.copyOf(data, data.length - SIGNATURE_LEN);
        byte[] signature = Arrays.copyOfRange(data, data.length - SIGNATURE_LEN, data.length);

        // Load vendor public key from trusted keystore
        KeyStore ks = KeyStore.getInstance("JKS");
        Path ksPath = Path.of("/etc/firmware/vendor-keys.jks");
        if (!Files.exists(ksPath)) {
            System.err.println("Keystore not found");
            return false;
        }
        try (InputStream is = Files.newInputStream(ksPath)) {
            ks.load(is, "changeit".toCharArray());
        }
        PublicKey pubKey = ks.getCertificate("vendor-signing").getPublicKey();

        Signature sig = Signature.getInstance("SHA256withRSA");
        sig.initVerify(pubKey);
        sig.update(signedData);
        return sig.verify(signature);
    }

    /**
     * Extract and install firmware segments to flash partitions.
     */
    private static void installSegments(FirmwarePackage pkg) throws Exception {
        Path outputDir = Path.of("/var/firmware/active");
        Files.createDirectories(outputDir);

        for (int i = 0; i < pkg.segments.size(); i++) {
            Segment seg = pkg.segments.get(i);
            // Allocate buffer for segment data
            // BUG: if segLen was negative (from signed short parse),
            // the segment was skipped above... BUT if segLen is in range
            // 32768-65535 (0x8000-0xFFFF), getShort() returns negative,
            // the 'continue' skips it. However, for values 0-32767 it works.
            // The REAL bug: offset + segLen overflow check is flawed.
            // If offset=60000 and segLen=32000 (both valid positive),
            // but payloadLen=65536, then offset+segLen=92000 > 65536
            // would be caught. But with signed confusion on segLen,
            // an attacker can craft offset=65530, segLen=-6 (0xFFFA as short)
            // which passes all checks, gets 'continue'd... WAIT.
            // 
            // Actually the real exploitable path: segLen=32767 (0x7FFF)
            // passes as positive. offset=40000. payloadLen=50000.
            // offset+segLen = 72767 > 50000 -> rejected. OK.
            //
            // The ACTUAL exploit: The 'continue' on negative segLen means
            // segments with large lengths (>32767) are silently dropped,
            // but the segment was ALREADY ADDED to the list before the
            // continue check... NO wait, let me re-read.
            // 
            // Looking again: the continue is BEFORE segments.add().
            // So negative segLen segments are skipped. But the issue is
            // that segLen=0x7FFF (32767) is the max valid positive short.
            // An attacker who controls the package binary can set:
            //   offset = 0, segLen = 0x7FFE (32766), flags with COMPRESSED
            // Then in installSegments, the decompression can produce
            // output larger than expected.
            //
            // Let me redesign: the REAL vulnerability is simpler.
            // The 'continue' means we skip adding bad segments, but
            // the ByteBuffer position has already advanced. This is fine.
            //
            // ACTUAL VULNERABILITY: Look at the check more carefully:
            // if (offset + segLen > payloadLen) - when segLen is negative
            // (e.g., -1), offset + (-1) = offset - 1 which is < payloadLen
            // so the check PASSES. Then segments.add() IS called with
            // negative segLen. The 'if (segLen < 0) continue' is checked
            // AFTER the add? No... let me restructure the code to make
            // the bug work properly.

            byte[] segData = new byte[seg.length]; // negative length throws
            System.arraycopy(pkg.rawData, seg.offset, segData, 0, seg.length);

            if ((seg.flags & FLAG_COMPRESSED) != 0) {
                segData = decompress(segData);
            }

            Path outFile = outputDir.resolve("segment_" + i + ".bin");
            Files.write(outFile, segData);
            System.out.println("Installed segment " + i + " (" + segData.length + " bytes)");
        }
    }

    private static byte[] decompress(byte[] compressed) throws Exception {
        // Simple zlib decompression
        java.util.zip.Inflater inflater = new java.util.zip.Inflater();
        inflater.setInput(compressed);
        ByteArrayOutputStream bos = new ByteArrayOutputStream(compressed.length * 2);
        byte[] tmp = new byte[4096];
        while (!inflater.finished()) {
            int count = inflater.inflate(tmp);
            if (count == 0 && inflater.needsInput()) break;
            bos.write(tmp, 0, count);
        }
        inflater.end();
        return bos.toByteArray();
    }

    static class Segment {
        final int offset;
        final int length;
        final int flags;
        Segment(int offset, int length, int flags) {
            this.offset = offset;
            this.length = length;
            this.flags = flags;
        }
    }

    static class FirmwarePackage {
        final List<Segment> segments;
        final int payloadStart;
        final int payloadLen;
        final byte[] rawData;
        FirmwarePackage(List<Segment> segments, int payloadStart, int payloadLen, byte[] rawData) {
            this.segments = segments;
            this.payloadStart = payloadStart;
            this.payloadLen = payloadLen;
            this.rawData = rawData;
        }
    }
}
